components.css:
.main-nav { display: flex; align-items: stretch; gap: 1.3rem; }
.main-nav a {
  display: grid;
  place-items: center;
  min-block-size: 3.65rem;
  min-inline-size: 44px;
  border-bottom: 2px solid transparent;
  color: #4e5c6b;
  font-weight: 650;
  text-align: center;
  text-decoration: none;
  word-break: keep-all;
}
.main-nav a:hover, .main-nav a[aria-current="page"] { color: #214c85; }
.main-nav a[aria-current="page"] { border-color: #214c85; }
